import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Multi-Cluster and Protocol Visibility with the New Ceph Dashboard","description":"","frontmatter":{"title":"Multi-Cluster and Protocol Visibility with the New Ceph Dashboard","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph Dashboard","Multi-Cluster Management","Object Storage","Management Gateway","File System"],"categories":["存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Multi-Cluster_and_Protocol_Visibility_with_the_New_Ceph_Dashboard.md","filePath":"posts/2025/Multi-Cluster_and_Protocol_Visibility_with_the_New_Ceph_Dashboard.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Multi-Cluster_and_Protocol_Visibility_with_the_New_Ceph_Dashboard.md"};function r(s,a,h,n,d,u){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>IBM工程师Ankosh分享了Ceph Dashboard的最新功能，重点讨论了多集群管理、对象存储增强、管理网关、文件系统改进和监控面板优化等主题。</p><h3 id="核心讨论内容" tabindex="-1">核心讨论内容 <a class="header-anchor" href="#核心讨论内容" aria-label="Permalink to &quot;核心讨论内容&quot;">​</a></h3><h4 id="_1-ceph-dashboard的重要性" tabindex="-1">1. Ceph Dashboard的重要性 <a class="header-anchor" href="#_1-ceph-dashboard的重要性" aria-label="Permalink to &quot;1. Ceph Dashboard的重要性&quot;">​</a></h4><ul><li>提供统一管理界面，支持block、file和object storage。</li><li>支持大规模集群的健康状态、性能指标和容量管理。</li><li>简化复杂操作，如CRUSH算法配置和PG管理。</li></ul><h4 id="_2-tentacle版本新功能" tabindex="-1">2. Tentacle版本新功能 <a class="header-anchor" href="#_2-tentacle版本新功能" aria-label="Permalink to &quot;2. Tentacle版本新功能&quot;">​</a></h4><ol><li><p><strong>多集群管理（Multicluster Management）</strong></p><ul><li>集中监控多集群指标，在Grafana中统一展示。</li><li>管理多个集群的资源，如OSD和MON。</li><li>跨集群告警统一展示。</li><li>支持跨集群数据复制，如RGW bucket复制。</li></ul></li><li><p><strong>对象存储增强（Object Enhancements）</strong></p><ul><li>跨集群复制，支持自动化token交换。</li><li>云分层，支持AWS S3等作为后端存储。</li><li>S3账户管理，实现多租户自服务。</li></ul></li><li><p><strong>管理网关（Management Gateway）</strong></p><ul><li>通过OAuth2/OIDC协议实现统一认证，支持SSO登录。</li><li>简化访问，通过单一入口访问所有管理服务。</li></ul></li><li><p><strong>文件系统改进（File Improvements）</strong></p><ul><li>支持SMB协议，管理SMB集群、用户和共享目录。</li><li>优化NFS UX，统一cluster和shares视图。</li></ul></li><li><p><strong>监控面板优化（Monitoring Dashboards）</strong></p><ul><li>跨集群监控，展示跨集群容量、告警和资源状态。</li><li>应用概览，按block、file、object分类统计存储使用情况。</li><li>NVMe监控，新增NVMe网关性能和容量指标面板。</li><li>增强文件系统详情，可视化metadata、IOPS等指标。</li></ul></li></ol><h4 id="_3-未来计划-roadmap" tabindex="-1">3. 未来计划（Roadmap） <a class="header-anchor" href="#_3-未来计划-roadmap" aria-label="Permalink to &quot;3. 未来计划（Roadmap）&quot;">​</a></h4><ul><li>提升易用性，优化NVMe配置流程。</li><li>改进故障排查，在告警中增加修复建议。</li><li>支持超大规模OSD集群。</li><li>完善监控面板，覆盖更多存储类型。</li></ul><h4 id="_4-行动项-action-items" tabindex="-1">4. 行动项（Action Items） <a class="header-anchor" href="#_4-行动项-action-items" aria-label="Permalink to &quot;4. 行动项（Action Items）&quot;">​</a></h4><ul><li>测试多集群功能，验证跨集群复制和Prometheus Federation的稳定性。</li><li>收集用户对S3账户管理和云分层的使用体验反馈。</li><li>推动从SAML迁移至OAuth2/OIDC。</li></ul><h4 id="_5-关键词保留-ceph-术语" tabindex="-1">5. 关键词保留（Ceph 术语） <a class="header-anchor" href="#_5-关键词保留-ceph-术语" aria-label="Permalink to &quot;5. 关键词保留（Ceph 术语）&quot;">​</a></h4><ul><li>CRUSH algorithm | RADOS | PG | Bluestore | RocksDB</li><li>Erasure Coding | Thin Provisioning | iSCSI | CIFS/POSIX</li><li>Kubernetes Integration | Hybrid Cloud | JBOD/NAS</li></ul><h4 id="_6-参与贡献" tabindex="-1">6. 参与贡献 <a class="header-anchor" href="#_6-参与贡献" aria-label="Permalink to &quot;6. 参与贡献&quot;">​</a></h4><ul><li>通过Ceph Dashboard Slack或邮件列表联系开发团队。</li></ul><p><strong>会议结束</strong></p>',16)])])}const p=e(o,[["render",r]]);export{c as __pageData,p as default};
